ruleSearch.bookList:
$.data[*]
<js>
(() => {
	list = Array.from(result).filter(item => item.type == "book")
	return list
})()

bookList = list.map(x => `https://api.wan123x.com/read/getBookDetail?book_id=${x.id}`)

d = java.ajaxAll(bookList).map(x => x.body());

$=(b,c)=>java.getString(b,c);

Array.from(list,(a,i)=>{
	list={
		name:$("name",a),
		author:$("$..author_name",d[i]),
		kind:$("$..category1&&$..category2&&$..role&&$..ability",d[i]),
		words:$("$..words",d[i]),
		lastc:$("",d[i]),
		intro:"&nbsp;&nbsp;" + $("$..intro",d[i]),
		cover:$("$..cover_url",d[i]),
		link:`https://api.wan123x.com/read/getCatalog?book_id=${$("$..book_id",d[i])}&catalog_order=asc`
		};
		return list
	});
</js>

ruleToc.nextTocUrl:
@js:(function(){
var h='';try{h=String(src||'');}catch(e){}
if(h.indexOf('pgBtn')<0){try{h=String(result||'');}catch(e2){}}
var u=null;
try{var d=org.jsoup.Jsoup.parse(h);var a=d.select('a.pgBtn');
for(var i=0;i<a.size();i++){if(String(a.get(i).text()).indexOf('\u4e0b\u4e00\u9875')>=0){var x=String(a.get(i).attr('href'));if(x){u=x;break;}}}
}catch(e3){}
if(!u){var m=h.match(/href="([^"]+)"[^>]*>\u4e0b\u4e00\u9875</);if(m)u=m[1];}
return u||null;
})()

