ruleContent.replaceRegex:
@js:
//去除章节简介与正文重复
if(/^◎/.test(result) ){
chapter = result.match(/◎([\s\S]+?)…*◎/)[1].replace(/\s/g,'');
chapter2=result.match(/◎[\s\S]+?◎([\s\S]+)/)[1].replace(/\s/g,'');

//前十个字相同就删除
num = 10
if(chapter.substring(0,num)==chapter2.substring(0,num)){
	result = result.replace(/◎[\s\S]+?◎/,'')
	}else{result}
}else{result}

ruleExplore.bookList:
@JSon:$..[?(@.novelName)]&&$..[?(@.novelname)]&&$.massage
<js>
if(result){
function remove(a,b){
let delIndexList = a; // 要删除的序列
 if (delIndexList.length !== 0) { 
for (let i = delIndexList.length - 1; i >= 0; i--) { b.splice(delIndexList[i], 1) } 
return b
}
}

if(baseUrl=='https://app-cdn.jjwxc.net/bookstore/getFullPage?channel=bhxs&version=3'||baseUrl.match(/novelfree/)){
list=JSON.parse(src);
for(i in list){
channelName=list[i].channelName;
blist=list[i].data;
if(blist!="undefined"){
for(j in blist){
blist[j].channelName=channelName
}}else{blist.channelName=channelName}

}
if(!baseUrl.match(/novelfree/)){
list=remove([0, 6,11,12,13],list)
}else{
list=remove([1],list)
}
result=JSON.stringify(list);}
else if(baseUrl.match(/signIn|getSearchForKeyWords/)){
result="{signIn:["+src+"]}"
}
else{result=result}
}else{result=""}
</js>
$..[?(@.novelName)]&&$..[?(@.novelname)]&&$.signIn[*]

